package ai.wizards.os.automation;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import org.json.JSONArray;
import org.json.JSONObject;
import org.junit.Test;

import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.util.Iterator;

/**
 * Web's Food voice table (web/food/rules.js, fixture generated by tools/gen-food-voice-fixture.mjs) through native's
 * matcher: every phrase must pick the same action web's own matcher picked, so the floating orb and side button hear
 * what the in-app orb hears.
 */
public class AutomationShortcutsParityTest {
    @Test public void nativePicksWhatWebPicks() throws Exception {
        String json;
        try (InputStream in = getClass().getClassLoader().getResourceAsStream("food-voice-table.json")) {
            json = new String(in.readAllBytes(), StandardCharsets.UTF_8);
        }
        JSONObject fx = new JSONObject(json);
        JSONArray entries = fx.getJSONArray("table");
        JSONObject actions = new JSONObject();
        for (int i = 0; i < entries.length(); i++) {
            String key = entries.getJSONObject(i).getString("action");
            if (!actions.has(key)) actions.put(key, new JSONObject().put("op", "record").put("package", "com.grabtaxi.passenger").put("ref", key));
        }
        AutomationShortcuts.Table t = AutomationShortcuts.parse(new JSONObject().put("entries", entries).put("actions", actions));
        JSONArray cases = fx.getJSONArray("cases");
        assertTrue(cases.length() > 10);
        for (int i = 0; i < cases.length(); i++) {
            JSONObject c = cases.getJSONObject(i);
            String phrase = c.getString("phrase");
            assertEquals("native phrase form", phrase, AutomationPolicy.phrase(phrase, null));
            JSONObject got = AutomationShortcuts.match(t, phrase);
            String want = c.isNull("action") ? null : c.getString("action");
            assertEquals(phrase, want, got == null ? null : got.getString("ref"));
        }
        for (Iterator<String> it = actions.keys(); it.hasNext(); ) assertTrue(it.next().length() <= 64);
    }
}
